#include <optional>
#include <queue>
#include <stack>
#include <string_view>

bool balanced(std::string_view text) {
    std::stack<char> open;
    for (char c : text) {
        if (c == '(' || c == '[') {
            open.push(c);
        } else if (c == ')' || c == ']') {
            if (open.empty()) return false;             // check BEFORE top().
            char expected = (c == ')') ? '(' : '[';
            if (open.top() != expected) return false;   // read...
            open.pop();                                 // ...then remove.
        }
    }
    return open.empty();
}

std::optional<int> next_job(std::queue<int>& jobs) {
    if (jobs.empty()) return std::nullopt;             // emptiness made explicit.
    int job = jobs.front();
    jobs.pop();
    return job;
}
